export const AMENDMENT_PRINT_TITLE = "RESERVATION AMENDMENT CONFIRMATION";

export const AMENDMENT_PRINT_FOOTER =
  "This document is a reservation record generated by NORU PMS. It is not a receipt and does not confirm payment collection.";

export type AmendmentPrintChange = {
  item: string;
  before: string;
  after: string;
};

export type AmendmentPrintData = {
  propertyName: string;
  propertyContact: string | null;
  confirmationNumber: string;
  amendedAt: string | null;
  amendedBy: string | null;
  statusLabel: string | null;
  reference: string | null;
  changes: AmendmentPrintChange[];
  guestName: string;
  arrival: string;
  departure: string;
  nights: string;
  adults: string;
  children: string;
  roomType: string;
  assignedRoom: string;
  ratePlan: string | null;
  ratePerNight: string | null;
  roomTotal: string | null;
  source: string | null;
  marketSegment: string | null;
  externalReference: string | null;
  specialRequests: string | null;
  previousRoomTotal: string | null;
  updatedRoomTotal: string | null;
  roomTotalDifference: string | null;
  packagesSummary: string | null;
  packageAmount: string | null;
  policy: string | null;
  generatedAt: string | null;
};

export function amendmentConfirmationCopy(confirmationNumber: string): string {
  return `This document confirms the changes made to reservation ${confirmationNumber}. The updated reservation details shown below replace the corresponding details on the previous confirmation.`;
}
